package org.apache.commons.math3.dfp;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math3.FieldElement;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class Dfp_multiply_TriageGen3Test {

    private Dfp fieldInstance;

    @Before
    public void setUp() {
        // Dfp is typically used via its field, we need an instance to call multiply on.
        // Since we cannot call protected constructors, we use newInstance() 
        // which is public and provides a valid instance within the field context.
        fieldInstance = new Dfp(DfpField.dfp128).newInstance();
    }

    @Test
    public void testMultiply_PositiveInteger() {
        Dfp base = fieldInstance.newInstance(5);
        int multiplier = 10;
        Dfp result = base.multiply(multiplier);

        // 5 * 10 = 50
        assertEquals(new Dfp(fieldInstance.getField(), 50.0), result);
    }

    @Test
    public void testMultiply_NegativeInteger() {
        Dfp base = fieldInstance.newInstance(-5);
        int multiplier = 4;
        Dfp result = base.multiply(multiplier);

        // -5 * 4 = -20
        assertEquals(new Dfp(fieldInstance.getField(), -20.0), result);
    }

    @Test
    public void testMultiply_Zero() {
        Dfp base = fieldInstance.newInstance(123);
        int multiplier = 0;
        Dfp result = base.multiply(multiplier);

        // 123 * 0 = 0
        assertTrue(result.isZero());
        assertEquals(0, result.intValue());
    }

    @Test
    public void testMultiply_One() {
        Dfp base = fieldInstance.newInstance(99);
        int multiplier = 1;
        Dfp result = base.multiply(multiplier);

        // 99 * 1 = 99
        assertEquals(new Dfp(fieldInstance.getField(), 99.0), result);
    }

    @Test
    public void testMultiply_NegativeMultiplier() {
        Dfp base = fieldInstance.newInstance(7);
        int multiplier = -3;
        Dfp result = base.multiply(multiplier);

        // 7 * -3 = -21
        assertEquals(new Dfp(fieldInstance.getField(), -21.0), result);
    }

    @Test
    public void testMultiply_LargeInteger() {
        Dfp base = fieldInstance.newInstance(1000000);
        int multiplier = 1000;
        Dfp result = base.multiply(multiplier);

        // 1,000,000 * 1,000 = 1,000,000,000
        assertEquals(new Dfp(fieldInstance.getField(), 1000000000.0), result);
    }

    @Test
    public void testMultiply_IntegerMinValue() {
        Dfp base = fieldInstance.newInstance(2);
        int multiplier = Integer.MIN_VALUE;
        Dfp result = base.multiply(multiplier);

        // 2 * -2147483648 = -4294967296
        assertEquals(new Dfp(fieldInstance.getField(), -4294967296.0), result);
    }

    @Test
    public void testMultiply_BaseZero() {
        Dfp base = fieldInstance.getZero();
        int multiplier = 500;
        Dfp result = base.multiply(multiplier);

        // 0 * 500 = 0
        assertTrue(result.isZero());
    }
}
